// render.cpp - draws every van-core panel screen on a laptop, from the same
// nodes/vc_panel.h the firmware compiles. Built and run by panel_preview.py;
// see that file for how and why.
//
// Output: one binary PPM per scene, 320x172, in the directory given as argv[1].
// Pixels are stored as the panel stores them, RGB565, so banding in a fade
// shows here exactly as it will on the glass.

#include <cstdio>
#include <functional>
#include <string>
#include <vector>

#include "esphome/components/display/display.h"
#include "vc_panel.h"
#include "fonts_gen.h"  // generated by panel_preview.py from van-core.yaml's font: list

using namespace esphome;
using esphome::vc::panel::State;

// Text must stay inside the glass's safe area: clear of the rim and its fade,
// and of the rounded corners. A string that grows past it - a longer reason,
// a translated word, a three-digit value - fails the run here.
static const int SAFE_L = 10, SAFE_R = 310, SAFE_T = 6, SAFE_B = 167;
static const char *g_scene = "";
static bool g_unsafe = false;

// ---- a font backed by ESPHome's own glyph bitmaps -----------------------------
class HostFont : public display::BaseFont {
 public:
  explicit HostFont(const FontRec &f) : f_(f) {}

  void measure(const char *str, int *width, int *x_offset, int *baseline, int *height) override {
    *baseline = f_.baseline;
    *height = f_.height;
    int min_x = 0, x = 0;
    bool has_char = false;
    for (;;) {
      size_t len;
      uint32_t cp = next_cp(str, &len);
      if (len == 0) break;
      str += len;
      const GlyphRec *g = find(cp);
      if (!g) {
        missing(cp);
        if (f_.n) x += f_.glyphs[0].advance;
        continue;
      }
      min_x = has_char ? std::min(min_x, x + g->offset_x) : g->offset_x;
      x += g->advance;
      has_char = true;
    }
    *x_offset = min_x;
    *width = x - min_x;
  }

  void print(int x_start, int y_start, display::Display *d, Color color, const char *text,
             Color bg) override {
    start_ = text;
    int x_at = x_start;
    const int bpp_max = (1 << f_.bpp) - 1;
    for (;;) {
      size_t len;
      uint32_t cp = next_cp(text, &len);
      if (len == 0) break;
      text += len;
      const GlyphRec *g = find(cp);
      if (!g) {
        missing(cp);
        if (f_.n) {
          d->rectangle(x_at, y_start, f_.glyphs[0].advance, f_.height, color);
          x_at += f_.glyphs[0].advance;
        }
        continue;
      }
      const uint8_t *data = f_.data + g->data_off;
      uint8_t bitmask = 0, pixel_data = 0;
      bool outside = false;
      for (int gy = y_start + g->offset_y; gy != y_start + g->offset_y + g->height; gy++)
        for (int gx = x_at + g->offset_x; gx != x_at + g->offset_x + g->width; gx++) {
          int pixel = 0;
          for (int b = 0; b != f_.bpp; b++) {
            if (bitmask == 0) {
              pixel_data = *data++;
              bitmask = 0x80;
            }
            pixel <<= 1;
            if (pixel_data & bitmask) pixel |= 1;
            bitmask >>= 1;
          }
          if (pixel != 0 && (gx < SAFE_L || gx > SAFE_R || gy < SAFE_T || gy > SAFE_B))
            outside = true;
          if (pixel == bpp_max) {
            d->draw_pixel_at(gx, gy, color);
          } else if (pixel != 0) {
            float on = (float) pixel / bpp_max;
            d->draw_pixel_at(gx, gy,
                             Color((uint8_t) ((color.r - (float) bg.r) * on + bg.r),
                                   (uint8_t) ((color.g - (float) bg.g) * on + bg.g),
                                   (uint8_t) ((color.b - (float) bg.b) * on + bg.b)));
          }
        }
      if (outside && !reported_) {
        fprintf(stderr, "%s: text outside the safe area: '%s' (%s)%c", g_scene, start_, f_.id, 10);
        g_unsafe = reported_ = true;
      }
      x_at += g->advance;
    }
    reported_ = false;
  }

 private:
  static uint32_t next_cp(const char *s, size_t *len) {
    const uint8_t *u = (const uint8_t *) s;
    if (u[0] == 0) { *len = 0; return 0; }
    if (u[0] < 0x80) { *len = 1; return u[0]; }
    if ((u[0] & 0xE0) == 0xC0) { *len = 2; return ((u[0] & 0x1F) << 6) | (u[1] & 0x3F); }
    if ((u[0] & 0xF0) == 0xE0) {
      *len = 3;
      return ((u[0] & 0x0F) << 12) | ((u[1] & 0x3F) << 6) | (u[2] & 0x3F);
    }
    *len = 4;
    return ((u[0] & 0x07) << 18) | ((u[1] & 0x3F) << 12) | ((u[2] & 0x3F) << 6) | (u[3] & 0x3F);
  }
  const GlyphRec *find(uint32_t cp) const {
    int lo = 0, hi = f_.n - 1;
    while (lo <= hi) {
      int mid = (lo + hi) / 2;
      if (f_.glyphs[mid].cp == cp) return &f_.glyphs[mid];
      if (f_.glyphs[mid].cp < cp) lo = mid + 1;
      else hi = mid - 1;
    }
    return nullptr;
  }
  void missing(uint32_t cp) const {
    // The firmware logs this and draws a box; here it is fatal to the run, so
    // a glyph missing from van-core.yaml is found on the laptop, not the van.
    fprintf(stderr, "MISSING GLYPH U+%04X in font %s\n", (unsigned) cp, f_.id);
    g_missing = true;
  }
  const FontRec &f_;
  const char *start_ = "";
  bool reported_ = false;

 public:
  static bool g_missing;
};
bool HostFont::g_missing = false;

// ---- a 320x172 RGB565 framebuffer ---------------------------------------------
class Panel : public display::Display {
 public:
  static constexpr int PW = 320, PH = 172;
  uint16_t px[PW * PH] = {};
  void draw_pixel_at(int x, int y, Color c) override {
    if (x < 0 || y < 0 || x >= PW || y >= PH) return;
    px[y * PW + x] = (uint16_t) (((c.r >> 3) << 11) | ((c.g >> 2) << 5) | (c.b >> 3));
  }
  int get_width() override { return PW; }
  int get_height() override { return PH; }
  bool save(const std::string &path) const {
    FILE *fp = fopen(path.c_str(), "wb");
    if (!fp) return false;
    fprintf(fp, "P6\n%d %d\n255\n", PW, PH);
    for (int i = 0; i < PW * PH; i++) {
      const uint16_t v = px[i];
      const uint8_t r5 = v >> 11, g6 = (v >> 5) & 0x3F, b5 = v & 0x1F;
      const uint8_t rgb[3] = {(uint8_t) ((r5 << 3) | (r5 >> 2)), (uint8_t) ((g6 << 2) | (g6 >> 4)),
                              (uint8_t) ((b5 << 3) | (b5 >> 2))};
      fwrite(rgb, 1, 3, fp);
    }
    fclose(fp);
    return true;
  }
};

static const FontRec &font(const char *id) {
  for (int i = 0; i < N_FONTS; i++)
    if (strcmp(FONTS[i].id, id) == 0) return FONTS[i];
  fprintf(stderr, "font %s is not in van-core.yaml\n", id);
  exit(2);
}

// ---- scenes -------------------------------------------------------------------
// The cases that break layouts: widest glyph runs (100 %, -10.5 degC), every
// rim colour, both degraded paths, every action screen and every toast.
static State base() {
  State s;
  s.ble = true; s.probe = true; s.reason = "off";
  s.have_soc = s.have_flow = s.have_rem = true;
  s.soc = 62; s.win = 420; s.wout = 35; s.remaining_h = 14.2f;
  s.fridge_c = 4.6f; s.cabin_c = 21.3f; s.have_cabin = true;
  s.t_off = 4; s.t_on = 7; s.t_hard = 10; s.sleep_ceiling = 6;
  s.uptime_s = 3 * 86400 + 4 * 3600 + 12 * 60; s.heap_kb = 104;
  s.have_charge_cap = true; s.charge_cap = 100;
  s.hold_s = 3;
  return s;
}
static void fridge_on(State &s) { s.ac_on = true; s.fridge_req = true; s.reason = "fridge"; }
static void cooking(State &s, unsigned min) {
  s.ac_on = true; s.manual = true; s.reason = "manual"; s.manual_left_s = min * 60;
}

struct Scene {
  const char *name;
  std::function<void(State &)> set;
};

int main(int argc, char **argv) {
  const std::string out = argc > 1 ? argv[1] : ".";
  HostFont hero(font("f_hero")), unit(font("f_unit")), big(font("f_big")), title(font("f_title")),
      body(font("f_body")), small(font("f_small")), icon_s(font("f_icon_s")),
      icon_m(font("f_icon_m")), icon_l(font("f_icon_l")), soc(font("f_soc")), mid(font("f_mid"));
  const vc::panel::Fonts F{&hero,   &unit,   &big,    &title, &body, &small,
                           &icon_s, &icon_m, &icon_l, &soc,   &mid};

  const std::vector<Scene> scenes = {
      {"01_energy_sun", [](State &s) {}},
      {"02_energy_fridge", [](State &s) { fridge_on(s); s.soc = 88; s.win = 380; s.wout = 310; }},
      {"03_energy_cooking", [](State &s) { cooking(s, 38); s.soc = 71; s.win = 120; s.wout = 1850; s.remaining_h = 2.4f; }},
      {"04_energy_low", [](State &s) { fridge_on(s); s.soc = 12; s.win = 0; s.wout = 70; s.remaining_h = 2.1f; }},
      {"05_energy_full", [](State &s) { s.soc = 100; s.win = 610; s.wout = 30; }},
      {"06_energy_ble_lost", [](State &s) { s.ble = false; s.force = true; s.ac_on = true; s.reason = "ble lost"; s.have_soc = s.have_flow = s.have_rem = false; }},
      {"07_energy_starting", [](State &s) { s.boot = true; s.force = true; s.ac_on = true; s.reason = "boot"; }},
      {"08_energy_sleep_night", [](State &s) { s.sleep = true; s.soc = 57; s.win = 0; s.wout = 12; s.remaining_h = 38; }},
      {"08b_energy_no_flow_no_cabin", [](State &s) { s.win = 0; s.wout = 0; s.have_cabin = false; }},
      {"08c_energy_charger_and_cooking", [](State &s) { cooking(s, 30); s.soc = 47; s.win = 1180; s.wout = 1850; s.remaining_h = 1.2f; }},
      {"09b_fault_frame_switched_off", [](State &s) { s.rim = false; s.ble = false; s.force = true; s.ac_on = true; s.reason = "ble lost"; s.have_soc = s.have_flow = s.have_rem = false; }},
      {"09c_park_armed_blink_on", [](State &s) { s.rim = false; s.park_q = true; s.blink = true; }},
      // Readings that exist but are NaN, as ESPHome holds them after a failed
      // read: must draw as missing, never as "nan" (2026-10-16, cabin probe).
      {"08d_nan_readings", [](State &s) { s.cabin_c = NAN; s.soc = NAN; s.win = NAN; s.remaining_h = NAN; }},
      {"30b_diag_nan", [](State &s) { s.page = 6; s.cabin_c = NAN; s.fridge_c = NAN; }},
      {"09_energy_fridge_no_frame", [](State &s) { fridge_on(s); s.soc = 88; s.win = 380; s.wout = 310; s.rim = false; }},
      {"10_fridge_ok", [](State &s) { s.page = 1; }},
      {"11_fridge_cooling", [](State &s) { s.page = 1; fridge_on(s); s.fridge_c = 7.9f; }},
      {"12_fridge_sleep", [](State &s) { s.page = 1; s.sleep = true; s.fridge_c = 2.4f; }},
      {"13_fridge_hard", [](State &s) { s.page = 1; s.ac_on = true; s.fridge_req = true; s.reason = "fridge (hard)"; s.fridge_c = 11.2f; }},
      {"14_fridge_probe_stale", [](State &s) { s.page = 1; s.probe = false; s.force = true; s.ac_on = true; s.reason = "probe stale"; }},
      {"15_fridge_freezing", [](State &s) { s.page = 1; s.fridge_c = -10.5f; }},
      {"16_fridge_cooking", [](State &s) { s.page = 1; cooking(s, 32); s.fridge_c = 5.2f; }},
      {"17_fridge_park_armed", [](State &s) { s.page = 1; s.park_q = true; }},
      {"18_strip_crowded", [](State &s) { s.page = 3; cooking(s, 42); s.sleep = true; s.drive = true; }},
      {"19_strip_ble_lost_drive", [](State &s) { s.ble = false; s.force = true; s.ac_on = true; s.reason = "ble lost"; s.drive = true; s.have_soc = s.have_flow = s.have_rem = false; }},
      {"20_water", [](State &s) { s.page = 2; }},
      {"30_diag", [](State &s) { s.page = 6; fridge_on(s); }},
      {"40_cooking", [](State &s) { s.page = 3; cooking(s, 42); }},
      {"41_sleep_off", [](State &s) { s.page = 4; }},
      {"42_sleep_on", [](State &s) { s.page = 4; s.sleep = true; }},
      {"43_park_off", [](State &s) { s.page = 5; }},
      {"44_park_armed", [](State &s) { s.page = 5; s.park_q = true; }},
      {"45_park_on", [](State &s) { s.page = 5; s.parked = true; s.reason = "parked"; }},
      {"50_parked_view", [](State &s) { s.parked = true; s.parked_view = true; s.reason = "parked"; s.parked_d = 3.2f; }},
      {"60_hold_cooking", [](State &s) { s.holding = true; s.hold_frac = 0.55f; }},
      {"61_hold_park", [](State &s) { s.page = 5; s.park_q = true; s.holding = true; s.hold_frac = 0.8f; }},
      {"63_hold_start", [](State &s) { s.holding = true; s.hold_frac = 0.02f; }},
      {"62_hold_parked_view", [](State &s) { s.parked = true; s.parked_view = true; s.reason = "parked"; s.parked_d = 3.2f; s.holding = true; s.hold_frac = 0.3f; }},
      {"70_toast_ac_on", [](State &s) { cooking(s, 45); s.toast = 1; s.toast_added_s = 45 * 60; }},
      {"71_toast_plus30", [](State &s) { cooking(s, 75); s.toast = 2; s.toast_added_s = 30 * 60; }},
      {"72_toast_max", [](State &s) { cooking(s, 180); s.toast = 3; s.toast_added_s = 12 * 60; }},
      {"73_toast_off", [](State &s) { fridge_on(s); s.toast = 4; s.toast_was_on = true; }},
      {"74_toast_parked_off_cooking", [](State &s) { cooking(s, 45); s.toast = 5; }},
      {"75_toast_sleep_on", [](State &s) { s.sleep = true; s.toast = 6; }},
      {"76_toast_sleep_off", [](State &s) { s.toast = 7; }},
      {"77_toast_parked_off", [](State &s) { s.toast = 8; }},
  };

  // Sanity: any scene may be asked for alone (argv[2]).
  const std::string only = argc > 2 ? argv[2] : "";
  for (const Scene &sc : scenes) {
    if (!only.empty() && only != sc.name) continue;
    State s = base();
    sc.set(s);
    g_scene = sc.name;
    static Panel p;
    vc::panel::draw(p, s, F);
    if (!p.save(out + "/" + sc.name + ".ppm")) {
      fprintf(stderr, "cannot write %s\n", sc.name);
      return 1;
    }
  }
  if (HostFont::g_missing) return 3;
  return g_unsafe ? 4 : 0;
}
